import{_ as e,c as n,o as t,a0 as a}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Getuigenissen van spelers","description":"","frontmatter":{},"headers":[],"relativePath":"nl/testimonials.md","filePath":"nl/testimonials.md"}');const o=e({name:"nl/testimonials.md"},[["render",function(e,i,o,r,s,l){return t(),n("div",null,[...i[0]||(i[0]=[a('<h1 id="getuigenissen-van-spelers" tabindex="-1">Getuigenissen van spelers <a class="header-anchor" href="#getuigenissen-van-spelers" aria-label="Permalink to &quot;Getuigenissen van spelers&quot;">​</a></h1><p>Echte feedback van top-pétanquespelers die de middelen van Pétanque Academy hebben gebruikt om hun mentale spel en wedstrijdprestaties te verbeteren.</p><div class="tip custom-block"><p class="custom-block-title">Authentiek en anoniem</p><p>Deze getuigenissen vertegenwoordigen authentieke feedback van spelers op verschillende competitieniveaus. Alle getuigenissen zijn anoniem om de privacy van spelers te beschermen en eerlijke uitwisseling te stimuleren.</p></div><h2 id="regionale-en-nationale-concurrenten" tabindex="-1">Regionale en nationale concurrenten <a class="header-anchor" href="#regionale-en-nationale-concurrenten" aria-label="Permalink to &quot;Regionale en nationale concurrenten&quot;">​</a></h2><h3 id="quot-het-inner-coach-framework-heeft-alles-veranderd-quot" tabindex="-1">&quot;Het Inner Coach-framework heeft alles veranderd&quot; <a class="header-anchor" href="#quot-het-inner-coach-framework-heeft-alles-veranderd-quot" aria-label="Permalink to &quot;&amp;quot;Het Inner Coach-framework heeft alles veranderd&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ik speel al 12 jaar competitief pétanque en ik dacht dat ik alles wist. Maar ik was mijn eigen grootste vijand – ik bekritiseerde mezelf constant na elke fout. Het raamwerk &#39;Innerlijke Coach versus Innerlijke Criticus&#39; uit de module &#39;Mentale Kracht&#39; gaf me een compleet andere manier om met mezelf te praten tijdens wedstrijden.&quot;</em></p><p><em>Binnen twee maanden merkten mijn teamgenoten het verschil. Ik was rustiger, herstelde sneller van mislukte worpen en genoot weer echt van de competitie. Ik behaalde dit jaar de 3e plaats op de regionale kampioenschappen – mijn beste resultaat ooit.</em></p></blockquote><p><strong>— Regionaal kampioen, Frankrijk</strong></p><hr><h3 id="quot-eindelijk-iemand-die-elite-ontwikkeling-begrijpt-quot" tabindex="-1">&quot;Eindelijk iemand die elite-ontwikkeling begrijpt&quot; <a class="header-anchor" href="#quot-eindelijk-iemand-die-elite-ontwikkeling-begrijpt-quot" aria-label="Permalink to &quot;&amp;quot;Eindelijk iemand die elite-ontwikkeling begrijpt&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;De meeste pétanque-trainingen bestaan simpelweg uit &#39;meer oefenen&#39; of &#39;aan je techniek werken&#39;. Maar als je al meer dan 15 jaar speelt, is dat niet het probleem. Het probleem is om je techniek onder druk toe te passen.&quot;</em></p><p><em>De Zone-module legde precies uit wat ik ervoer: te veel nadenken tijdens het uitvoeren van taken, in de analytische modus blijven hangen terwijl ik in een flow-modus moest zijn. De praktische technieken om van modus te wisselen zijn echt een gamechanger geweest.</em></p><p><em>Dit is de eerste bron die ik heb gevonden die daadwerkelijk ingaat op het mentale aspect van het spel op topniveau.</em></p></blockquote><p><strong>— Speler van het Zweedse nationale team</strong></p><hr><h3 id="quot-de-workshopmethodologie-heeft-onze-club-getransformeerd-quot" tabindex="-1">&quot;De workshopmethodologie heeft onze club getransformeerd&quot; <a class="header-anchor" href="#quot-de-workshopmethodologie-heeft-onze-club-getransformeerd-quot" aria-label="Permalink to &quot;&amp;quot;De workshopmethodologie heeft onze club getransformeerd&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ik ben clubtrainer en ik heb de workshopgids gebruikt om een mentale trainingssessie te geven aan onze acht beste spelers. Het kader voor psychologische veiligheid en de gestructureerde discussievorm zorgden voor gesprekken die we nog nooit eerder hadden gevoerd.&quot;</em></p><p><em>Spelers vertelden openhartig over hun innerlijke critici, hun reacties onder druk en de communicatieproblemen binnen het team. Het was ontzettend krachtig. We organiseren deze sessies nu maandelijks en de teamcultuur is volledig veranderd.</em></p></blockquote><p><strong>— Clubtrainer, Duitsland</strong></p><hr><h2 id="toernooispelers" tabindex="-1">Toernooispelers <a class="header-anchor" href="#toernooispelers" aria-label="Permalink to &quot;Toernooispelers&quot;">​</a></h2><h3 id="quot-praktische-hulpmiddelen-die-echt-werken-quot" tabindex="-1">&quot;Praktische hulpmiddelen die echt werken&quot; <a class="header-anchor" href="#quot-praktische-hulpmiddelen-die-echt-werken-quot" aria-label="Permalink to &quot;&amp;quot;Praktische hulpmiddelen die echt werken&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ik heb wel eens boeken over sportpsychologie gelezen, maar die zijn altijd te algemeen of te academisch. De doelensjabloon en het dagboeksjabloon van Pétanque Academy zijn precies wat ik nodig had: praktisch, specifiek voor pétanque en direct bruikbaar.&quot;</em></p><p><em>Ik heb de doelensjabloon gebruikt en had binnen 30 minuten een duidelijk ontwikkelingsplan voor 3 maanden. De dagboeksjabloon helpt me niet alleen resultaten, maar ook mijn mentale prestaties bij te houden. Deze tools zijn goud waard.</em></p></blockquote><p><strong>— Toernooispeler, Spanje</strong></p><hr><h3 id="quot-mindfulness-technieken-werken-ook-in-competitieverband-quot" tabindex="-1">&quot;Mindfulness-technieken werken ook in competitieverband&quot; <a class="header-anchor" href="#quot-mindfulness-technieken-werken-ook-in-competitieverband-quot" aria-label="Permalink to &quot;&amp;quot;Mindfulness-technieken werken ook in competitieverband&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ik was sceptisch over mindfulness – het leek me te &#39;soft&#39; voor competitieve sporten. Maar de technieken in de mindfulnessmodule zijn praktisch en specifiek. De reset met drie ademhalingen, de lichaamsscan om spanning op te sporen, de oefeningen om je te concentreren op het huidige moment.&quot;</em></p><p><em>Ik oefen elke ochtend 10 minuten en kan deze technieken nu tijdens wedstrijden gebruiken. Als ik de druk voel oplopen, heb ik de middelen om ermee om te gaan. Dit heeft een meetbaar verschil gemaakt in mijn prestaties.</em></p></blockquote><p><strong>— Toernooispeler, Nederland</strong></p><hr><h3 id="quot-het-begrijpen-van-flow-toestanden-heeft-mijn-potentieel-ontsloten-quot" tabindex="-1">&quot;Het begrijpen van flow-toestanden heeft mijn potentieel ontsloten&quot; <a class="header-anchor" href="#quot-het-begrijpen-van-flow-toestanden-heeft-mijn-potentieel-ontsloten-quot" aria-label="Permalink to &quot;&amp;quot;Het begrijpen van flow-toestanden heeft mijn potentieel ontsloten&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ik had wel eens potjes gespeeld waarin alles op zijn plek viel – waarin ik niet hoefde na te denken, maar gewoon perfect speelde. Maar ik wist niet hoe ik die staat consistent kon bereiken. De Zone-module legde de wetenschap erachter uit en gaf me praktische technieken.</em>&quot;</p><p><em>Door meer te leren over tijdelijke hypofrontaliteit, het omschakelen tussen planning en uitvoering te begrijpen en flow-triggers te oefenen, is die kennis veel toegankelijker geworden voor optimale prestaties. Ik speel mijn beste pétanque ooit.</em></p></blockquote><p><strong>— Regionale speler, Frankrijk</strong></p><hr><h2 id="teamspelers" tabindex="-1">Teamspelers <a class="header-anchor" href="#teamspelers" aria-label="Permalink to &quot;Teamspelers&quot;">​</a></h2><h3 id="quot-werd-de-teamgenoot-die-iedereen-wil-hebben-quot" tabindex="-1">&quot;Werd de teamgenoot die iedereen wil hebben&quot; <a class="header-anchor" href="#quot-werd-de-teamgenoot-die-iedereen-wil-hebben-quot" aria-label="Permalink to &quot;&amp;quot;Werd de teamgenoot die iedereen wil hebben&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Technisch gezien was ik sterk, maar ik had moeite met teamwedstrijden. De module Teamdynamiek liet me zien dat een goede teamspeler zijn niet alleen draait om goede worpen, maar ook om communicatie, vertrouwen en psychologische veiligheid.&quot;</em></p><p><em>Ik heb geleerd om vertrouwen uit te spreken, strategie helder te communiceren en teamgenoten te steunen na fouten. Binnen een paar maanden veranderde ik van iemand die werd gemeden in iemand die graag als partner werd gezien. We hebben dit jaar het regionale teamkampioenschap gewonnen.</em></p></blockquote><p><strong>— Teamspeler, Italië</strong></p><hr><h3 id="quot-het-communicatiekader-heeft-onze-samenwerking-gered-quot" tabindex="-1">&quot;Het communicatiekader heeft onze samenwerking gered&quot; <a class="header-anchor" href="#quot-het-communicatiekader-heeft-onze-samenwerking-gered-quot" aria-label="Permalink to &quot;&amp;quot;Het communicatiekader heeft onze samenwerking gered&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Mijn vaste partner en ik hadden spanningen – verschillende speelstijlen, slechte communicatie en oplopende frustratie. De module &#39;Teamspeler&#39; gaf ons een kader om dit constructief te bespreken.</em>&quot;</p><p><em>We leerden over communicatiepatronen, over het opbouwen van vertrouwen en over het creëren van psychologische veiligheid. We voerden openhartige gesprekken in de vorm van een workshop. Onze samenwerking is sterker dan ooit, en onze resultaten bewijzen dat.</em></p></blockquote><p><strong>— Dubbelteam, Noorwegen</strong></p><hr><h2 id="coaches-en-trainers" tabindex="-1">Coaches en trainers <a class="header-anchor" href="#coaches-en-trainers" aria-label="Permalink to &quot;Coaches en trainers&quot;">​</a></h2><h3 id="quot-zo-ziet-topcoaching-eruit-quot" tabindex="-1">&quot;Zo ziet topcoaching eruit&quot; <a class="header-anchor" href="#quot-zo-ziet-topcoaching-eruit-quot" aria-label="Permalink to &quot;&amp;quot;Zo ziet topcoaching eruit&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ik geef al 20 jaar pétanquetraining, voornamelijk gericht op techniek. Maar ik zag spelers met een uitstekende techniek falen onder druk. De trainingsmodules gaven me het kader om het mentale aspect van het spel systematisch aan te pakken.&quot;</em></p><p><em>De handleiding van het trainingskamp hielp me bij het samenstellen van een weekendprogramma dat technische training combineerde met mentale training. De feedback van de spelers was fantastisch: ze zeiden dat het de meest waardevolle training was die ze ooit hadden gevolgd.</em></p></blockquote><p><strong>— Coach, Frankrijk</strong></p><hr><h3 id="quot-een-op-bewijs-gebaseerde-benadering-van-mentale-training-quot" tabindex="-1">&quot;Een op bewijs gebaseerde benadering van mentale training&quot; <a class="header-anchor" href="#quot-een-op-bewijs-gebaseerde-benadering-van-mentale-training-quot" aria-label="Permalink to &quot;&amp;quot;Een op bewijs gebaseerde benadering van mentale training&amp;quot;&quot;">​</a></h3><blockquote><p>&quot;Wat ik het meest waardeer, is dat dit niet zomaar motiverende praatjes zijn. De inhoud is gebaseerd op daadwerkelijk psychologisch onderzoek – flow-state wetenschap, mindfulness-studies, prestatiepsychologie. Maar het is vertaald naar praktische, toepasbare technieken.&quot;</p><p><em>Ik gebruik deze modules als basis voor mentale coaching van mijn topspelers. De gestructureerde aanpak, de duidelijke kaders, de praktische oefeningen – dit is materiaal van professioneel niveau.</em></p></blockquote><p><strong>— Sportpsycholoog en jeu de boules-coach, VK</strong></p><hr><h2 id="gemeenschappelijke-thema-39-s" tabindex="-1">Gemeenschappelijke thema&#39;s <a class="header-anchor" href="#gemeenschappelijke-thema-39-s" aria-label="Permalink to &quot;Gemeenschappelijke thema&amp;#39;s&quot;">​</a></h2><h3 id="wat-spelers-het-meest-waarderen" tabindex="-1">Wat spelers het meest waarderen <a class="header-anchor" href="#wat-spelers-het-meest-waarderen" aria-label="Permalink to &quot;Wat spelers het meest waarderen&quot;">​</a></h3><p>Op basis van feedback geven spelers consequent de volgende punten aan:</p><ol><li><strong>Praktische, direct toepasbare inhoud</strong> - Geen theorie, maar technieken die je vandaag nog kunt gebruiken.</li><li><strong>Pétanque-specifiek</strong> - Ontworpen voor de unieke uitdagingen van jeu de boules</li><li><strong>Focus op topniveau</strong> - Richt zich op de mentale kant van het spel, niet op de basistechniek.</li><li><strong>Gestructureerde kaders</strong> - Duidelijke systemen, geen vaag advies.</li><li><strong>Gratis en toegankelijk</strong> - Geen betaalmuren, beschikbaar voor iedereen.</li></ol><h3 id="meetbare-resultaten" tabindex="-1">Meetbare resultaten <a class="header-anchor" href="#meetbare-resultaten" aria-label="Permalink to &quot;Meetbare resultaten&quot;">​</a></h3><p>Spelers melden verbeteringen op de volgende gebieden:</p><ul><li>Wedstrijdprestaties en -resultaten</li><li>Consistentie onder druk</li><li>Hersteltijd na fouten</li><li>Teamcommunicatie en -dynamiek</li><li>Plezier in de competitie</li><li>Mentale veerkracht</li></ul><h2 id="deel-je-ervaring" tabindex="-1">Deel je ervaring <a class="header-anchor" href="#deel-je-ervaring" aria-label="Permalink to &quot;Deel je ervaring&quot;">​</a></h2><p>Heeft u gebruikgemaakt van de materialen van Pétanque Academy? We horen graag over uw ervaring.</p><p><strong>Stuur uw getuigenis per e-mail naar:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Testimonial" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Erbij betrekken:</strong></p><ul><li>Jouw ervaringsniveau</li><li>Welke bronnen heb je gebruikt?</li><li>Welke impact ze hadden</li><li>Of we uw feedback mogen delen (naam optioneel)</li></ul><p>Jouw verhaal kan andere spelers helpen deze hulpmiddelen te ontdekken.</p><hr><h2 id="aan-de-slag" tabindex="-1">Aan de slag <a class="header-anchor" href="#aan-de-slag" aria-label="Permalink to &quot;Aan de slag&quot;">​</a></h2><p>Ben je klaar om je mentale vaardigheden te verbeteren?</p><div class="tip custom-block"><p class="custom-block-title">Begin hier</p><ul><li><strong>Nieuw in mentale training?</strong> → <a href="/en/education/the-zone/">De Zone</a></li><li><strong>Heb je moeite met druk?</strong> → <a href="/en/education/mental-strength/">Mentale kracht</a></li><li><strong>Teamuitdagingen?</strong> → <a href="/en/education/team-player/">Teamdynamiek</a></li><li><strong>Wilt u structuur?</strong> → <a href="/en/goal-template">Doelsjabloon</a></li></ul></div>',64)])])}]]);export{i as __pageData,o as default};
